13	function isNeighbor([x, y]: Cell, [otherX, otherY]: Cell): boolean {
14	  const isSameCell = x === otherX && y === otherY;
15	  return (
16	    !isSameCell && Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1
17	  );
18	}
