function isNeighbor([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  const isSameCell = x === otherX && y === otherY;
  const isAdjacent =
    isWithinOneStep(x, otherX) && isWithinOneStep(y, otherY);
  return isAdjacent && !isSameCell;
}

function isWithinOneStep(coordinate: number, other: number): boolean {
  return Math.abs(coordinate - other) <= 1;
}
